export const EDUCATION_RECORDS:EducationRecord[]=[
 {fmaIds:['FMA55676'],names:['brain','segment of brain'],displayName:'Brain',system:'nervous',summary:'The brain is the central organ of the nervous system. Its connected regions integrate sensory information and support movement, memory, language, emotion and the regulation of essential body functions.',location:'Inside the cranial cavity, continuous with the spinal cord through the brainstem.',mainFunction:'Processes information and coordinates conscious, automatic, sensory and motor activity.',facts:['Its three broad divisions are the cerebrum, cerebellum and brainstem.','The folded cerebral cortex increases the surface area available for neural processing.','The cerebellum is especially important for coordination, posture and balance.'],clinical:'Because different regions have specialized roles, the effects of injury depend strongly on the location involved.',sourceIds:['brain','nervous']},
 {fmaIds:['FMA7088'],names:['heart'],displayName:'Heart',system:'cardiac',summary:'The heart is a muscular, four-chambered pump that maintains blood flow through the lungs and the rest of the body.',location:'In the middle mediastinum of the chest, between the lungs and behind the sternum.',mainFunction:'Pumps blood through the pulmonary and systemic circulations.',facts:['The right side sends blood to the lungs; the left side sends blood to the body.','Four main valves help maintain one-way flow through the chambers.','The left ventricle has a thick muscular wall suited to pumping into the systemic circulation.'],clinical:'Valve, muscle and electrical-conduction disorders can each disrupt efficient circulation.',sourceIds:['heart','circulation']},
 {fmaIds:['FMA7309'],names:['right lung'],displayName:'Right lung',system:'respiratory',summary:'The right lung is one of the paired organs of gas exchange and is divided into upper, middle and lower lobes.',location:'In the right side of the thoracic cavity, enclosed by pleura and protected by the rib cage.',mainFunction:'Transfers oxygen into blood and removes carbon dioxide from it.',facts:['The right lung normally has three lobes.','Air reaches microscopic alveoli through a branching airway tree.','Pleural membranes provide a low-friction surface as the lung moves during breathing.'],clinical:'Changes in ventilation, airways or pulmonary blood flow can reduce gas exchange.',sourceIds:['lungs','respiration']},
 {fmaIds:['FMA7310'],names:['left lung'],displayName:'Left lung',system:'respiratory',summary:'The left lung is a paired gas-exchange organ shaped partly around the position of the heart.',location:'In the left side of the thoracic cavity, enclosed by pleura and protected by the rib cage.',mainFunction:'Transfers oxygen into blood and removes carbon dioxide from it.',facts:['The left lung normally has two lobes.','Its cardiac notch accommodates part of the heart.','Like the right lung, it contains a branching bronchial tree ending in alveoli.'],clinical:'The close relationship of the lung, pleura and heart is important when interpreting chest symptoms and imaging.',sourceIds:['lungs','respiration']},
 {fmaIds:['FMA7197'],names:['liver'],displayName:'Liver',system:'digestive',summary:'The liver is a large metabolic organ that processes absorbed nutrients, produces bile, handles many substances in the blood and synthesizes important proteins.',location:'Primarily in the right upper abdomen, beneath the diaphragm and protected partly by the lower ribs.',mainFunction:'Supports metabolism, digestion, detoxification, protein synthesis and nutrient storage.',facts:['The liver receives blood from both the portal vein and the hepatic artery.','Hepatocytes are arranged in functional microscopic units called lobules.','Bile made by the liver helps the intestine process fats.'],clinical:'Liver dysfunction can affect metabolism, clotting, digestion and the handling of medicines and toxins.',sourceIds:['liver','abdomen']},
 {fmaIds:['FMA7202'],names:['gallbladder'],displayName:'Gallbladder',system:'digestive',summary:'The gallbladder is a small pear-shaped organ beneath the liver that stores and concentrates bile made by the liver.',location:'In a shallow fossa on the visceral surface of the liver in the right upper abdomen.',mainFunction:'Stores concentrated bile and releases it into the duodenum during digestion.',facts:['Its lining absorbs water and electrolytes, making stored bile more concentrated.','The cystic duct connects the gallbladder with the wider biliary duct system.','The body can still deliver bile to the intestine after the gallbladder is removed.'],clinical:'Gallstones may obstruct bile flow and can inflame the gallbladder or affect nearby ducts.',sourceIds:['gallbladder','biliary']},
 {fmaIds:['FMA7148'],names:['stomach'],displayName:'Stomach',system:'digestive',summary:'The stomach is a muscular hollow organ that temporarily stores food and begins its mechanical and chemical digestion.',location:'Mostly in the upper left and central abdomen, between the esophagus and duodenum.',mainFunction:'Mixes food with gastric secretions and meters the resulting contents into the small intestine.',facts:['Its main regions are the cardia, fundus, body and pylorus.','Folds called rugae let the wall expand as the stomach fills.','Mucus helps protect the stomach lining from its acidic contents.'],clinical:'Disruption of the protective lining can contribute to inflammation or ulceration.',sourceIds:['stomach','digestive']},
 {fmaIds:['FMA7198'],names:['pancreas'],displayName:'Pancreas',system:'digestive',summary:'The pancreas is both a digestive gland and an endocrine organ, producing digestive secretions as well as hormones including insulin and glucagon.',location:'Across the upper posterior abdomen, with its head beside the duodenum and its tail directed toward the spleen.',mainFunction:'Delivers digestive enzymes and bicarbonate to the duodenum and releases metabolic hormones into blood.',facts:['Most of the pancreas lies behind the peritoneal cavity.','Its acinar cells make the exocrine pancreatic juice.','Its endocrine islets release hormones directly into the bloodstream.'],clinical:'Inflammation or obstruction can affect both digestion and nearby biliary structures.',sourceIds:['pancreas','abdomen']},
 {fmaIds:['FMA7196'],names:['spleen'],displayName:'Spleen',system:'lymphatic',summary:'The spleen is a highly vascular lymphatic organ that filters blood, supports immune surveillance and helps remove aging blood cells.',location:'In the left upper abdomen between the stomach and diaphragm, deep to the lower ribs.',mainFunction:'Filters circulating blood and supports immune responses to blood-borne material.',facts:['The spleen is the largest organ of the lymphatic system.','Its visceral surface is shaped by neighboring stomach, kidney, colon and pancreas.','A connective-tissue capsule surrounds the splenic tissue.'],clinical:'Because it is highly vascular, injury to the spleen can cause substantial internal bleeding.',sourceIds:['spleen','lymphatic']},
 {fmaIds:['FMA7200'],names:['small intestine'],displayName:'Small intestine',system:'digestive',summary:'The small intestine is the main site for nutrient digestion and absorption and also contributes to endocrine and immune functions.',location:'Between the stomach and large intestine, occupying much of the central and lower abdomen.',mainFunction:'Completes much of digestion and absorbs nutrients into blood and lymph.',facts:['It consists of the duodenum, jejunum and ileum.','Its mucosal folds, villi and microvilli greatly enlarge the absorptive surface.','The mesentery carries vessels, nerves and lymphatics to the jejunum and ileum.'],clinical:'Disease affecting its lining can interfere with absorption and lead to nutrient deficiencies.',sourceIds:['smallIntestine','digestive']},
 {fmaIds:['FMA7201'],names:['large intestine'],displayName:'Large intestine',system:'digestive',summary:'The large intestine receives material from the small intestine and forms, stores and moves fecal material toward elimination.',location:'Frames much of the small intestine, extending from the cecum through the colon to the rectum and anal canal.',mainFunction:'Recovers remaining water and electrolytes and compacts intestinal contents.',facts:['It is shorter than the small intestine but has a wider lumen.','The colon includes ascending, transverse, descending and sigmoid regions.','Resident microorganisms contribute to the colonic environment and metabolism.'],clinical:'Its broad blood supply and regional anatomy are important in inflammation, obstruction and surgery.',sourceIds:['largeIntestine','digestive']},
 {fmaIds:['FMA14546'],names:['transverse colon'],displayName:'Transverse colon',system:'digestive',summary:'The transverse colon is the mobile portion of the large intestine that crosses the upper abdomen from the right colic flexure toward the left colic flexure.',location:'Across the upper abdomen, suspended from the posterior abdominal wall by the transverse mesocolon.',mainFunction:'Moves and compacts colonic contents while continuing recovery of water and electrolytes.',facts:['It links the ascending and descending regions of the colon.','Its suspended position allows more mobility than the fixed ascending and descending colon.','The middle colic vessels travel within its mesocolon.'],clinical:'Its mobility and vascular territories matter during abdominal surgery and imaging.',sourceIds:['largeIntestine','mesocolon']},
 {fmaIds:['FMA14647'],names:['transverse mesocolon'],displayName:'Transverse mesocolon',system:'connective',summary:'The transverse mesocolon is a double fold of peritoneum associated with the transverse colon. It suspends the colon and provides a route for vessels, nerves and lymphatics.',location:'Extends from the transverse colon to the posterior abdominal wall, crossing the mid-abdomen near the pancreas.',mainFunction:'Supports the transverse colon while carrying its neurovascular and lymphatic connections.',facts:['It divides parts of the peritoneal cavity into upper and lower regions.','The middle colic vessels and accompanying lymphatics help identify it on imaging.','It is continuous with several neighboring peritoneal attachments.'],clinical:'Its connections can influence how fluid or disease processes travel through the abdomen.',sourceIds:['mesocolon','abdomen']},
 {fmaIds:['FMA7204'],names:['right kidney'],displayName:'Right kidney',system:'urinary',summary:'The right kidney is a retroperitoneal organ that filters blood, forms urine and helps regulate fluid, electrolyte and acid-base balance.',location:'Behind the abdominal cavity on the right side of the spine; it usually sits slightly lower than the left kidney because of the liver.',mainFunction:'Filters blood and adjusts the composition and volume of body fluids while producing urine.',facts:['Urine drains from collecting structures into the renal pelvis and then the ureter.','The kidney receives a rich blood supply for continuous filtration.','The adrenal gland lies near its upper pole but is a separate endocrine organ.'],clinical:'Obstruction, infection or reduced blood flow can impair renal function and urine drainage.',sourceIds:['urinary','abdomen']},
 {fmaIds:['FMA7205'],names:['left kidney'],displayName:'Left kidney',system:'urinary',summary:'The left kidney is a retroperitoneal organ that filters blood, forms urine and helps regulate fluid, electrolyte and acid-base balance.',location:'Behind the abdominal cavity on the left side of the spine, near the spleen and posterior abdominal wall.',mainFunction:'Filters blood and adjusts the composition and volume of body fluids while producing urine.',facts:['The left kidney commonly lies slightly higher than the right.','Urine leaves it through the left ureter on the way to the bladder.','Microscopic nephrons carry out filtration and selective reabsorption.'],clinical:'Kidney function is closely linked with blood pressure, electrolyte balance and waste removal.',sourceIds:['urinary','abdomen']},
 {fmaIds:['FMA15900'],names:['urinary bladder'],displayName:'Urinary bladder',system:'urinary',summary:'The urinary bladder is a distensible muscular reservoir that receives urine from both ureters and stores it before urination.',location:'In the pelvis behind the pubic bones; its upper surface rises toward the abdomen as it fills.',mainFunction:'Stores urine and coordinates its controlled release into the urethra.',facts:['The detrusor is the smooth muscle within the bladder wall.','The bladder has an apex, body, fundus and neck.','Sensory and motor pathways coordinate filling and emptying.'],clinical:'Bladder function depends on coordinated muscle activity and intact central, autonomic and somatic nerve pathways.',sourceIds:['bladder','urinary']},
 {fmaIds:['FMA7647'],names:['spinal cord'],displayName:'Spinal cord',system:'nervous',summary:'The spinal cord is the long column of nervous tissue linking the brain with spinal nerves and organizing many reflex responses.',location:'Within the vertebral canal, extending from the brainstem to the upper lumbar region in most adults.',mainFunction:'Carries sensory information toward the brain, motor commands toward the body and supports reflex circuits.',facts:['It is part of the central nervous system together with the brain.','Cervical and lumbar enlargements are associated with nerves serving the limbs.','One anterior and two posterior spinal arteries contribute to its longitudinal blood supply.'],clinical:'Because neural pathways are arranged by level and tract, the location of injury influences the pattern of impairment.',sourceIds:['spinalCord','nervous']},
 {fmaIds:['FMA54449','FMA54450'],names:['eye','right eye','left eye'],displayName:'Eye',system:'sensory',summary:'The eye is a sensory organ that focuses light onto the retina, where photoreceptors begin converting light into neural signals.',location:'Within the bony orbit, connected to the brain by the optic nerve and moved by extraocular muscles.',mainFunction:'Receives and focuses light and begins the neural processing required for vision.',facts:['The cornea and lens both contribute to focusing light on the retina.','Rods are especially sensitive in low light, while cones support color and high-acuity vision.','The optic disc creates a natural blind spot because it contains no photoreceptors.'],clinical:'Clear optical media, a healthy retina and an intact optic pathway are all required for useful vision.',sourceIds:['eye','sensory']},
 {fmaIds:['FMA52781'],names:['ear','external ear'],displayName:'Ear',system:'sensory',summary:'The ear collects sound and contains specialized structures for hearing; deeper vestibular structures also sense balance and head movement.',location:'On and within the temporal region of the skull, extending from the external ear to the middle and inner ear.',mainFunction:'Transforms sound vibration into neural signals and contributes to balance and spatial orientation.',facts:['The cochlea is the spiral inner-ear structure responsible for auditory transduction.','Hair cells in the organ of Corti convert mechanical movement into neural signals.','The vestibular apparatus detects angular movement, linear acceleration and gravity.'],clinical:'Hearing and balance symptoms may arise from different parts of the ear or their neural pathways.',sourceIds:['ear','sensory']},
 {fmaIds:['FMA7163'],names:['skin'],displayName:'Skin',system:'integumentary',summary:'Skin forms the body surface and acts as a physical and immune barrier while contributing to sensation, temperature regulation and fluid balance.',location:'Covers the external body surface and continues with specialized linings at body openings.',mainFunction:'Protects internal tissues and helps regulate temperature, sensation and water exchange.',facts:['Its major layers are the epidermis, dermis and deeper hypodermis.','Cutaneous receptors detect touch, pressure, vibration, temperature and pain.','Changes in skin blood flow and sweating help regulate body temperature.'],clinical:'Loss of the skin barrier can disturb fluid balance, temperature control and protection from infection.',sourceIds:['skin','sensory']},
 {fmaIds:['FMA9611','FMA24474','FMA24475'],names:['femur','right femur','left femur'],displayName:'Femur',system:'skeletal',summary:'The femur is the long bone of the thigh and a major weight-bearing element of the lower limb.',location:'Between the hip and knee, articulating proximally with the pelvis and distally with the tibia and patella.',mainFunction:'Transfers load and provides leverage and attachment sites for muscles that move the hip and knee.',facts:['Its rounded head forms the ball of the hip joint.','The distal condyles participate in the knee joint.','Like other long bones, it contains dense cortical bone around internal trabecular bone and marrow spaces.'],clinical:'The blood supply of the femoral head and the forces across the bone are important in fractures and joint disease.',sourceIds:['bone','connective']},
 {fmaIds:['FMA46565'],names:['skull'],displayName:'Skull',system:'skeletal',summary:'The skull is the bony framework of the head, protecting the brain and supporting the face, sensory organs and upper airway.',location:'At the upper end of the vertebral column, surrounding the cranial cavity and forming the facial skeleton.',mainFunction:'Protects the brain and provides cavities, openings and attachment sites for nerves, vessels and muscles.',facts:['The cranial base contains foramina that transmit cranial nerves and blood vessels.','Many skull bones form directly through intramembranous ossification.','Air-filled paranasal sinuses occupy parts of several craniofacial bones.'],clinical:'Skull-base anatomy is clinically important because many major nerves and vessels pass through compact bony openings.',sourceIds:['bone','brain']},
 {fmaIds:['FMA24485','FMA24486','FMA24487'],names:['patella','right patella','left patella'],displayName:'Patella',system:'skeletal',summary:'The patella, or kneecap, is a sesamoid bone embedded within the quadriceps tendon at the front of the knee.',location:'Anterior to the knee joint, between the quadriceps tendon above and the patellar ligament below.',mainFunction:'Improves the leverage of the quadriceps during knee extension, guides the extensor mechanism and shields deeper anterior joint structures.',partOf:'The patellofemoral joint and quadriceps extensor mechanism.',articulations:['Patellar surface of the femur through medial and lateral posterior facets.'],attachments:['Quadriceps tendon at the superior pole and margins.','Patellar ligament at the inferior pole.','Medial and lateral retinacular fibers along its borders.'],relatedStructures:['Femur','Quadriceps femoris','Patellar ligament','Tibial tuberosity'],facts:['The patella is the largest sesamoid bone in the human body.','Its contact with the femur changes as the knee moves through flexion and extension.','Its position within the extensor mechanism increases the quadriceps moment arm.'],clinical:'Patellar alignment and tracking are important educational landmarks when studying the mechanics of knee movement.',sourceIds:['patella','bone']},
 {fmaIds:['FMA9613','FMA52788','FMA52789'],names:['parietal bone','right parietal bone','left parietal bone'],displayName:'Parietal bone',system:'skeletal',summary:'Each parietal bone is a broad, curved cranial bone that forms much of the roof and upper side wall of the skull.',location:'Between the frontal bone anteriorly and occipital bone posteriorly, meeting its partner at the midline sagittal suture.',mainFunction:'Forms the protective calvaria around the cerebral hemispheres and provides attachment for cranial fascia and muscle.',partOf:'The calvaria, the upper protective vault of the skull.',articulations:['Opposite parietal bone at the sagittal suture.','Frontal bone at the coronal suture.','Occipital bone at the lambdoid suture.','Temporal bone at the squamosal suture.'],relatedStructures:['Frontal bone','Temporal bone','Occipital bone','Sagittal suture'],facts:['The paired parietal bones meet along the sagittal suture.','The pterion is a junctional region involving the parietal, frontal, temporal and sphenoid bones.','Cranial sutures are fibrous joints between skull bones.'],clinical:'Sutures and junctional landmarks around the parietal bone help orient skull imaging and surface anatomy.',sourceIds:['skullAnatomy','bone']},
 {fmaIds:['FMA23899','FMA24464','FMA24465'],names:['first metacarpal bone','right first metacarpal bone','left first metacarpal bone'],displayName:'First metacarpal bone',system:'skeletal',summary:'The first metacarpal is the long bone of the thumb ray, linking the wrist-side trapezium with the thumb’s proximal phalanx.',location:'In the lateral metacarpus at the base of the thumb, distal to the trapezium and proximal to the first proximal phalanx.',mainFunction:'Supports the thumb and transmits forces across the carpometacarpal and metacarpophalangeal joints during grasp and opposition.',partOf:'The metacarpus and skeletal framework of the thumb.',articulations:['Trapezium proximally at the first carpometacarpal joint.','Proximal phalanx of the thumb distally at the first metacarpophalangeal joint.'],relatedStructures:['Trapezium','Proximal phalanx of thumb','Thenar muscles','First metacarpophalangeal joint'],facts:['The metacarpus contains five metacarpal bones.','The saddle-shaped first carpometacarpal joint gives the thumb exceptional mobility.','The first metacarpophalangeal joint contributes to flexion used during grasp.'],clinical:'The first metacarpal’s mobile base and stable distal articulation are useful landmarks for understanding thumb opposition and precision grip.',sourceIds:['hand','thumbJoint']},
 {fmaIds:['FMA32555','FMA33581','FMA33583'],names:['ascending part of trapezius','ascending part of right trapezius','ascending part of left trapezius'],displayName:'Ascending part of trapezius',system:'muscular',summary:'The ascending, or lower, part of trapezius is the inferior fiber group of the broad superficial trapezius muscle.',location:'Across the lower portion of the upper back, with fibers passing upward and laterally toward the medial end of the scapular spine.',mainFunction:'Depresses the scapula and works with the upper trapezius and serratus anterior to assist upward rotation of the scapula.',partOf:'The trapezius muscle and superficial posterior shoulder girdle.',attachments:['Lower thoracic spinous processes through their intervening supraspinous ligaments.','Medial end of the spine of the scapula.'],relatedStructures:['Descending trapezius','Transverse trapezius','Scapula','Serratus anterior'],facts:['The trapezius is one of the broadest and most superficial muscles of the upper back.','Its fiber groups have different lines of pull and cooperate to position the scapula.','The lower fibers help stabilize the scapula during movements that raise the arm overhead.'],clinical:'Coordinated trapezius and serratus anterior activity is important for normal scapular rotation during elevation of the arm.',sourceIds:['trapezius','muscle']},
];

interface FamilyContext {name:string;displayName:string;laterality?:'Left'|'Right'}
export interface EducationFamilyRecord {
 id:string;
 name:string;
 systems?:SystemId[];
 exactNames?:string[];
 phrases?:string[];
 excludePhrases?:string[];
 identify?:(context:FamilyContext)=>string;
 location?:string;
 mainFunction?:string;
 facts:string[];
 sourceIds:SourceId[];
}

const sideMember=(context:FamilyContext,family:string)=>context.laterality
 ? `${context.displayName} is the ${context.laterality.toLowerCase()}-sided member or subdivision of the paired ${family}.`
 : `${context.displayName} is represented as a member or subdivision of the ${family}.`;

