const FACT_CATEGORY_NAMES:Record<SystemId,string>={skeletal:'Skeletal system',muscular:'Muscular system',cardiac:'Heart',sensory:'Sensory organs',arterial:'Arteries',venous:'Veins',nervous:'Nervous system',respiratory:'Respiratory system',digestive:'Digestive system',urinary:'Urinary system',lymphatic:'Lymphatic system',endocrine:'Endocrine system',reproductive:'Reproductive system',integumentary:'Body surface',connective:'Connective tissues'};

export const DISCOVERY_FACTS:AnatomyFact[]=FACT_INPUTS.map(fact=>{
 const source=EDUCATION_SOURCES[fact.sourceId];
 return {...fact,category:fact.category??(fact.system?FACT_CATEGORY_NAMES[fact.system]:'General anatomy'),sourceName:source.name,sourceUrl:source.url};
});

export function normalizeStructureName(name:string){return name.toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();}

export function normalizeFmaId(reference?:string){
 if(!reference)return '';
 const compact=reference.trim().replace(/\s+/g,'');
 const match=compact.match(/^(?:FMA:?)?(\d+)$/i);
 return match?`FMA${match[1]}`:compact.toUpperCase();
}

